const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const { BrowserWindow, dialog } = require('electron');
module.exports = async ({ run, click, disk, shot, window }) => {
  const originalTable = disk().data.timetables.activeId;
  // Seed an old category in the isolated workspace, then exercise the real UI.
  const legacyWorkspace = disk();
  const legacyNote = legacyWorkspace.data.journal.entries.find(entry => entry.id === 'demo-journal-1');
  assert.ok(legacyNote); legacyNote.kind = 'experience';
  assert.equal((await run(`window.jeeWeaveDesktop.writeWorkspace(${JSON.stringify(legacyWorkspace)})`)).ok, true);
  const loaded = new Promise(resolve => window.webContents.once('did-finish-load', resolve));
  window.webContents.reload(); await loaded;
  for (let i = 0; i < 100 && !await run('!!document.querySelector("#desktop-journal-new")'); i++) await new Promise(resolve => setTimeout(resolve, 30));
  await click('[data-view="notes"]');
  assert.equal(await run('document.querySelector(".main").dataset.activeView'), 'notes');
  assert.equal(await run('document.querySelector(".nav [data-view=notes]").textContent.trim()'), '笔记');
  assert.equal(await run('document.querySelector(".desktop-quick-note").textContent.trim()'), '记一笔');
  assert.equal(await run('document.querySelector("#view-journal h1").textContent'), '笔记');
  assert.equal(await run('document.querySelector(".desktop-journal-secondary").open'), false);
  const selectStatus = async status => {
    if (status !== 'active') await run('document.querySelector(".desktop-journal-secondary").open=true;true');
    await click(`[data-journal-status="${status}"]`);
  };
  await run('document.querySelector("#desktop-journal-kind").value="review";document.querySelector("#desktop-journal-kind").dispatchEvent(new Event("change",{bubbles:true}));true');
  assert.equal(await run('document.querySelectorAll("[data-journal-id]").length'), 1);
  await click('[data-journal-edit="demo-journal-1"]');
  assert.equal(await run('document.querySelector("#desktop-journal-form").elements.kind.value'), 'review');
  await click('#desktop-journal-form [data-journal-close]');
  assert.equal(disk().data.journal.draft.kind, 'experience', 'opening/closing old drafts does not rewrite their kind');
  await click('#desktop-journal-resume'); await click('#desktop-journal-discard'); await click('#desktop-journal-confirm-discard');
  assert.equal(disk().data.journal.entries.find(entry => entry.id === legacyNote.id).kind, 'experience');
  await click('#desktop-journal-clear');
  await click('#desktop-journal-new');
  assert.equal(await run('document.querySelector("#desktop-journal-form").elements.kind.value'), 'uncategorized');
  assert.deepEqual(await run('[...document.querySelector("#desktop-journal-form").elements.kind.options].map(o=>o.textContent)'), ['未分类', '见闻', '感受', '想法', '摘录', '复盘']);
  const body = '每天给自己一点时间，记下感悟和感受。\n<img src=x onerror=window.noteInjected=true>\n今天想把学习中的想法慢慢整理起来。';
  await run(`(()=>{const f=document.querySelector('#desktop-journal-form');f.elements.body.value=${JSON.stringify(body)};f.elements.date.value='2026-10-20';f.elements.kind.value='feeling';f.elements.tags.value='生活 学习';f.dispatchEvent(new Event('input',{bubbles:true}));return true})()`);
  assert.equal(disk().data.journal.draft.body, body, 'typing is durably saved before publication');
  assert.equal(await run('document.querySelector("#desktop-journal-save-state").textContent.includes("尚未存为笔记")'), true);
  assert.deepEqual(await run(`(()=>{const t=document.querySelector('#desktop-journal-form [name=body]');t.focus();t.setSelectionRange(2,2);t.dispatchEvent(new CompositionEvent('compositionstart',{data:'感',bubbles:true}));t.dispatchEvent(new InputEvent('input',{data:'感',isComposing:true,bubbles:true}));t.dispatchEvent(new CompositionEvent('compositionend',{data:'感',bubbles:true}));return [t.selectionStart,document.activeElement===t]})()`), [2, true]);
  window.setSize(1280, 900); await shot('journal-editor-wide.png');
  window.setSize(900, 700); await shot('journal-editor-compact.png');
  assert.equal(await run('document.querySelector("#desktop-journal-dialog").getBoundingClientRect().right<=innerWidth'), true);
  await run('document.querySelector("#desktop-journal-form").requestSubmit();true');
  let note = disk().data.journal.entries.find(entry => !entry.example); assert.ok(note); const originalId = note.id, originalCreated = note.createdAt;
  assert.equal(note.title, ''); assert.equal(note.date, '2026-10-20'); assert.deepEqual(note.tags, ['生活', '学习']);
  assert.equal(await run('window.noteInjected'), undefined);
  await run('document.querySelector("#desktop-journal-search").value="<img";document.querySelector("#desktop-journal-search").dispatchEvent(new Event("input",{bubbles:true}));true');
  assert.equal(await run('document.querySelectorAll("[data-journal-id]").length'), 1);
  assert.equal(await run('document.querySelector(".desktop-journal-body").textContent.includes("<img")'), true);
  const exportFile = path.join(process.env.JEEWEAVE_WORKSPACE_TEST_EVIDENCE, 'journal-export.md');
  const exported = new Promise((resolve, reject) => {
    const timeout = setTimeout(() => reject(Error('Journal Markdown download did not finish')), 5000);
    window.webContents.session.once('will-download', (_event, item) => { item.setSavePath(exportFile); item.once('done', (_e, state) => { clearTimeout(timeout); state === 'completed' ? resolve() : reject(Error(`Journal download: ${state}`)); }); });
  });
  await click('#desktop-journal-export'); await exported;
  assert.ok(fs.readFileSync(exportFile, 'utf8').includes(body));
  assert.equal(await run('document.querySelector("#desktop-journal-export").textContent'), '导出筛选结果');
  await click('#desktop-journal-clear');
  const row = `[data-journal-id="${originalId}"]`;
  await click(`${row} [data-journal-action=archive]`); await selectStatus('archived');
  assert.equal(await run('document.querySelector(".desktop-journal-secondary summary").textContent'), '已归档');
  assert.equal(await run(`!!document.querySelector(${JSON.stringify(row)})`), true);
  await click(`${row} [data-journal-action=trash]`); await selectStatus('trash'); await click(`${row} [data-journal-action=restore]`);
  await selectStatus('archived'); await click(`${row} [data-journal-action=unarchive]`); await selectStatus('active');
  await click('#desktop-journal-new'); await run('document.querySelector("#desktop-journal-form [name=body]").value="明确删除的临时笔记";document.querySelector("#desktop-journal-form").requestSubmit();true');
  const temporary = disk().data.journal.entries.find(entry => !entry.example && entry.id !== originalId);
  assert.equal(temporary.kind, 'uncategorized', 'saving text requires no category, title or tags');
  await click(`[data-journal-edit="${temporary.id}"]`);
  await run('document.querySelector("#desktop-journal-form").elements.kind.value="excerpt";document.querySelector("#desktop-journal-form").requestSubmit();true');
  await run('document.querySelector("#desktop-journal-kind").value="excerpt";document.querySelector("#desktop-journal-kind").dispatchEvent(new Event("change",{bubbles:true}));true');
  assert.equal(await run('document.querySelectorAll("[data-journal-id]").length'), 1);
  assert.equal(await run('document.querySelector(".desktop-journal-meta span").textContent'), '摘录');
  await click('#desktop-journal-clear');
  await click(`[data-journal-id="${temporary.id}"] [data-journal-action=trash]`); await selectStatus('trash');
  await click(`[data-journal-id="${temporary.id}"] [data-journal-action=purge]`); assert.ok(disk().data.journal.entries.some(entry => entry.id === temporary.id));
  await click(`[data-journal-id="${temporary.id}"] [data-journal-action=purge]`); assert.equal(disk().data.journal.entries.some(entry => entry.id === temporary.id), false); await click('[data-journal-status=active]');
  await click(`[data-journal-edit="${originalId}"]`);
  assert.equal(await run('document.querySelector("#desktop-journal-save-state").textContent.includes("原笔记尚未更新")'), true);
  const file = path.join(process.env.JEEWEAVE_DATA_DIR, 'workspace.json'), before = fs.readFileSync(file, 'utf8'), rename = fs.renameSync;
  const showMessage = dialog.showMessageBoxSync; let asked = 0;
  try {
    fs.renameSync = (source, target) => { if (target === file) throw Error('fixture journal disk full'); return rename(source, target); };
    await run('document.querySelector("#desktop-journal-form [name=body]").value+=String.fromCharCode(10)+"失败后也不能丢失的文字";document.querySelector("#desktop-journal-form [name=body]").dispatchEvent(new Event("input",{bubbles:true}));true');
    assert.equal(fs.readFileSync(file, 'utf8'), before);
    assert.equal(await run('document.querySelector("#desktop-journal-error").hidden'), false);
    await click('#desktop-journal-form [data-journal-close]'); assert.equal(await run('document.querySelector("#desktop-journal-dialog").open'), true);
    await click('.nav [data-view="today"]'); assert.equal(await run('document.querySelector(".main").dataset.activeView'), 'notes');
    await click('#desktop-module-notes'); assert.equal(disk().data.preferences.modules.enabled.notes, true, 'failed draft blocks disabling before preferences are changed');
    dialog.showMessageBoxSync = () => { asked++; return 0; };
    window.close(); assert.equal(window.isDestroyed(), false); assert.equal(asked, 1, 'native close offers a return-to-save choice');
    const foreign = new BrowserWindow({ show: false, webPreferences: { sandbox: true, contextIsolation: true, preload: path.resolve(__dirname, '../../preload.cjs') } });
    await foreign.loadURL('about:blank'); assert.equal((await foreign.webContents.executeJavaScript('window.jeeWeaveDesktop.setUnsavedJournal(false)')).ok, false); foreign.destroy();
  } finally { fs.renameSync = rename; dialog.showMessageBoxSync = showMessage; }
  await click('#desktop-journal-retry'); assert.equal(disk().data.journal.draft.body.includes('不能丢失'), true);
  await run('document.querySelector("#desktop-journal-form").requestSubmit();true');
  note = disk().data.journal.entries.find(entry => entry.id === originalId); assert.equal(note.createdAt, originalCreated);
  assert.equal(note.body.includes('不能丢失'), true);
  await require('./connections-flow.cjs')({ run, click, disk, shot, window, note });
  window.setSize(1280, 900); await shot('journal-timeline-wide.png'); window.setSize(900, 700); await shot('journal-timeline-compact.png');
  await click('[data-view="settings"]'); await click('[data-theme="ink"]'); await click('[data-view="notes"]'); window.setSize(1280,900); await shot('journal-timeline-dark.png');
  await click('[data-view="settings"]'); await click('[data-theme="forest"]'); await click('[data-view="notes"]');
  await click('[data-view="plugins"]'); await click('#desktop-module-notes');
  assert.equal(await run('document.querySelector(".nav [data-view=notes]").hidden'), true);
  assert.equal(await run('document.querySelector("#desktop-journal-dialog")'), null);
  assert.equal(disk().data.journal.entries.some(entry => entry.id === originalId), true);
  await click('[data-command="notes.capture"]'); assert.equal(await run('document.querySelector("#desktop-journal-form")'), null);
  await click('#desktop-module-notes'); await click('[data-command="notes.capture"]');
  assert.equal(await run('document.querySelectorAll("#desktop-journal-dialog").length'), 1);
  await run('document.querySelector("#desktop-journal-form [name=body]").value="重开后继续写的草稿";document.querySelector("#desktop-journal-form [name=body]").dispatchEvent(new Event("input",{bubbles:true}));true');
  await click('#desktop-journal-form [data-journal-close]');
  await click('[data-view="settings"]'); await click('#desktop-developer-mode'); await click('[data-view="notes"]');
  assert.equal(await run('document.querySelector("#desktop-journal-example").hidden'), true);
  const count = disk().data.journal.entries.length; await click('#desktop-journal-example'); assert.equal(disk().data.journal.entries.length, count);
  assert.equal(await run('document.querySelectorAll("[data-journal-id]").length'), 1);
  await click('[data-view="settings"]'); await click('#desktop-developer-mode');
  assert.equal(disk().data.journal.draft.body, '重开后继续写的草稿');
  await click('[data-view="courses"]'); await click('#desktop-open-course-settings'); await click('#desktop-tab-semester');
  await run(`document.querySelector('#desktop-semester-select').value=${JSON.stringify(originalTable)};document.querySelector('#desktop-semester-select').dispatchEvent(new Event('change'));true`);
  await click('#desktop-close-course-settings');
  console.log('PASS: journal typing/IME-safe fields, literal text, draft durability, archive/trash, save failure and native-close veto, retry, module unload/reload, example guard and portable draft.');
};
